import 'package:flutter_test/flutter_test.dart';
import '../support/billing_fixture.dart';
void main(){test('interrupted prepare resumes, repeats harmlessly and cancelled round releases slot',()async{final f=BillingFixture();await f.seed();await f.owner.addSubscriber(name:'يدوي',phone:'',address:'',number:'1',startingMilli:0);await f.owner.addSubscriber(name:'مرتبط',phone:'',address:'',number:'2',startingMilli:0,userId:'c');final rid=await f.owner.openRound(DateTime.utc(2026,11,15));await f.db.collection('billingRounds').doc(rid).update({'status':'preparing'});await f.db.collection('readerRounds').doc('g').update({'status':'preparing'});final rows=await f.db.collection('meterAssignments').get();await rows.docs.first.reference.delete();await f.owner.prepare(rid);await f.owner.prepare(rid);expect((await f.db.collection('meterAssignments').get()).size,2);await expectLater(f.owner.cancelPreparation(rid),throwsStateError);await f.db.collection('billingRounds').doc(rid).update({'status':'preparing'});await f.db.collection('readerRounds').doc('g').update({'status':'preparing'});await f.owner.cancelPreparation(rid);await expectLater(f.owner.prepare(rid),throwsStateError);await f.owner.openRound(DateTime.utc(2026,11,16));expect((await f.db.collection('billingRounds').get()).size,2);});test('assignment before opening, during preparation and reassignment stay synchronized',()async{final f=BillingFixture();await f.seed();for(final uid in ['r1','r2']){await f.db.collection('meterStaff').doc(uid).set({'generatorId':'g','active':true,'name':uid});}final sid=await f.owner.addSubscriber(name:'يدوي',phone:'',address:'',number:'1',startingMilli:0);await f.owner.assignReader(sid,'r1');final rid=await f.owner.openRound(DateTime.utc(2026,11,15));final ref=f.db.collection('meterAssignments').doc('${rid}_$sid');expect((await ref.get()).data()!['readerUid'],'r1');await f.db.collection('billingRounds').doc(rid).update({'status':'preparing'});await f.db.collection('readerRounds').doc('g').update({'status':'preparing'});await f.owner.assignReader(sid,'r2');await f.owner.prepare(rid);expect((await ref.get()).data()!['readerUid'],'r2');await f.owner.assignReader(sid,'r1');expect((await ref.get()).data()!['readerUid'],'r1');});
}
